package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertMarketClient.*;import static org.junit.jupiter.api.Assertions.*;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.junit.jupiter.api.Test;
class AlertCalendarPlanTest {
 static CalendarSnapshot calendar(Instant now,LocalDate start,LocalDate end,Set<LocalDate> closed){var days=new ArrayList<Day>();for(var d=start;!d.isAfter(end);d=d.plusDays(1))days.add(new Day(d,!closed.contains(d)&&d.getDayOfWeek().getValue()<6));return new CalendarSnapshot(UUID.randomUUID(),"baostock",start,end,now,hash(days),days);}
 static CalendarSnapshot calendar(Instant now){var today=now.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate();return calendar(now,today.minusDays(366),today,Set.of());}
 static String hash(List<Day> days){try{var text=new StringBuilder();for(var d:days)text.append(d.date()).append(':').append(d.open()?'1':'0').append('\n');return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Test void cutoffBeforeAndAfter20AndWeekendUseTradingCalendar(){var before=Instant.parse("2026-10-09T11:59:59Z");var after=Instant.parse("2026-10-09T12:00:00Z");assertEquals(LocalDate.of(2026,10,8),AlertScanPlan.expected(calendar(before),before,20));assertEquals(LocalDate.of(2026,10,9),AlertScanPlan.expected(calendar(after),after,20));var weekend=Instant.parse("2026-10-10T12:00:00Z");assertEquals(LocalDate.of(2026,10,9),AlertScanPlan.expected(calendar(weekend),weekend,20));}
 @Test void holidayCannotBeGuessedFromWeekday(){var now=Instant.parse("2026-10-09T12:00:00Z");var c=calendar(now,LocalDate.of(2025,10,8),LocalDate.of(2026,10,9),Set.of(LocalDate.of(2026,10,9)));assertEquals(LocalDate.of(2026,10,8),AlertScanPlan.expected(c,now,20));}
 @Test void expiredFutureMissingDatesAndBadHashAreRejected(){var now=Instant.parse("2026-10-10T12:00:00Z");var c=calendar(now);var missing=new ArrayList<>(c.days());missing.remove(100);for(var bad:List.of(new CalendarSnapshot(c.versionId(),c.provider(),c.start(),c.end(),now.minusSeconds(604801),c.sourcePayloadHash(),c.days()),new CalendarSnapshot(c.versionId(),c.provider(),c.start(),c.end(),now.plusSeconds(6),c.sourcePayloadHash(),c.days()),new CalendarSnapshot(c.versionId(),c.provider(),c.start(),c.end(),now,hash(missing),missing),new CalendarSnapshot(c.versionId(),c.provider(),c.start(),c.end(),now,"0".repeat(64),c.days())))assertThrows(RuntimeException.class,()->AlertScanPlan.expected(bad,now,20));}
 @Test void successfulGetWithShortCoverageDoesNotProveValidity(){var now=Instant.parse("2026-10-10T12:00:00Z");var c=calendar(now,LocalDate.of(2026,9,1),LocalDate.of(2026,10,10),Set.of());assertThrows(RuntimeException.class,()->AlertScanPlan.expected(c,now,20));}
}
